// IncomePage Examples: {"items":[{"amount_cents":4500000,"cfdi_uuid":null,"collected_on":null,"counterparty_kind":"pm","created_at":"2026-09-05T16:00:00Z","description":"Consultoría de procesos, septiembre","id":"0199d4a3-3c4d-7f5e-a061-7c8d9e0f1a23","invoiced_on":"2026-09-05","isr_withheld_cents":0,"iva_cents":720000,"iva_rate":"rate_16","iva_withheld_cents":0,"operation_kind":"business_services","pending_collection":true,"platform_activity":null,"regime_code":"601","residential_rent":false,"taxpayer_id":"0199d4a2-9a10-7d55-b2c3-4d5e6f7a8b91","updated_at":"2026-09-05T16:00:00Z","via_platform":false,"warnings":[],"withholding":{"cpa_unverified":false,"explanations":[{"rule_id":"ISR-2","text":"Como persona moral, no te retienen ISR en esta operación."},{"rule_id":"IVA-8","text":"Tampoco te retienen IVA en esta operación."}],"isr_cents":0,"isr_rate":"0","iva_basis":"none","iva_cents":0,"net_cents":5220000,"remit_due_on":null,"rule_ids":["ISR-2","IVA-8"],"table_version":"2026.1","withholder":"none"}}],"next_cursor":null,"totals":{"amount_cents":4500000,"count":1,"isr_withheld_cents":0,"iva_cents":720000,"iva_withheld_cents":0}}
