// SubscriptionStatus Examples: {"access":{"access":"trial","expenses_remaining":5,"incomes_remaining":3,"trial_days_left":3,"trial_ends_at":"2026-10-20T16:00:00Z"},"plan":null}
type SubscriptionStatus struct {
	// Access The caller's access state, computed by the server so the client never uses its own clock (OQ-D6). Per user, across all taxpayers (PRD Q2). One shape for every screen that needs it: the Home banner (`getDashboard`), the subscription status (M7) and the check before a create wizard (MODULES.md M7, PR #58 follow-up: M7-01 exposes this same schema to the app regardless of `module_subscriptions`). `trial`: `trial_ends_at` (exclusive), `trial_days_left` (whole days left, rounded up, at least 1 while the trial runs) and the records left of each kind. `read_only`: both counters `0`, the trial fields `null`. `pro`, `comp`: every other field `null` (no limit applies).
	//
	// Examples: {"access":"trial","expenses_remaining":5,"incomes_remaining":2,"trial_days_left":3,"trial_ends_at":"2026-10-20T16:00:00Z"}
	Access AccessSummary     `json:"access"`
	Plan   *SubscriptionPlan `json:"plan,omitempty"`
}

